        new Quote { Id = "https://en.wikiquote.org/wiki/David_W._Panuelo", Text = "It is imperative that we show our friends (Samoa), especially during their darkest hours, that we stand with them. Recent weeks have been very troubling for the Samoan People, who have been witnessing what is arguably a constitutional and political crisis.", Author = "David W. Panuelo" },
