        new Quote { Id = "https://en.wikiquote.org/wiki/Buddy_Wakefield", Text = "We are the fed up grass roots movement of goose flesh, hell bent on living this one life by the way we feel our spines, saying what we mean, refusing to allow the few to preach to the many when it is the many who need to be hearing eachother.", Author = "Buddy Wakefield" },
