        new Quote { Id = "https://en.wikiquote.org/wiki/Walter_M._Miller%2C_Jr.", Text = "The old man was sad as he sat on his porch. He knew so little of the Great Purpose. Why must his seed fling itself starward? He knew that it must — but he lacked a reason. His grandchildren played in the twilight, played space-games, although there was not yet a starship on the planet.", Author = "Walter M. Miller, Jr." },
