        new Quote { Id = "https://en.wikiquote.org/wiki/Ramcharitmanas", Text = "It is sinful to even see the face of a man who does not feel his friend's pain. Treat your own mountain-like pain as though it were a speck. Treat your friend's speck-like pain as though it were a mountain.", Author = "Ramcharitmanas" },
