        new Quote { Id = "https://en.wikiquote.org/wiki/Sara_Spencer_Washington", Text = "As long as there are women in the world, there will always be beauty establishments.", Author = "Sara Spencer Washington" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Justine_Tunney", Text = "It never ceases to amaze me how far people have to stretch in order to denounce the one corporation that gives away everything for free", Author = "Justine Tunney" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Abram_Kesupile", Text = "Madam Speaker, shortly after the commencement of our work, law enforcement agencies started to vigorously investigate the same issue, which then led to arrests of certain persons, some of whom were very key to our review and some who indeed had appeared before us.", Author = "Abram Kesupile" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Edmund_Dene_Morel", Text = "I was filled with determination, to do my best to expose and destroy what i then knew to be a legalized infamy, responsible for a vast destruction of human life.", Author = "Edmund Dene Morel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pandurang_Shastri_Athavale", Text = "It is my experience that awareness of the nearness of God and reverence for that power create reverence for self, reverence for the other, reverence for nature and reverence for all of creation.", Author = "Pandurang Shastri Athavale" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fyodor_Dostoyevsky", Text = "To study the meaning of man and of life — I am making significant progress here. I have faith in myself. Man is a mystery: if you spend your entire life trying to puzzle it out, then do not say that you have wasted your time. I occupy myself with this mystery, because I want to be a man.", Author = "Fyodor Dostoyevsky" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christopher_Langton", Text = "Biological systems are dynamical, not easily predicted, and are creative in many ways... In the old equilibrium worldview, ideas about change were dominated by the action-reaction formula. It was a clockwork world, ultimately predictable in boring ways.", Author = "Christopher Langton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Blues_rock", Text = "The blues gave rock a mother’s unconditional love, nurturing it through its difficult stages and always providing a welcome return no matter how far it strayed from home.", Author = "Blues rock" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jaipur_bombings", Text = "This is not a crime, we are in the middle of a war.", Author = "Jaipur bombings" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Safiur_Rahman_Mubarakpuri", Text = "Embrace Islam... If you two accept Islam, you will remain in command of your country; but if your refuse my Call, you’ve got to remember that all of your possessions are perishable. My horsemen will appropriate your land, and my Prophethood will assume preponderance over your kingship.", Author = "Safiur Rahman Mubarakpuri" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kamila_Shamsie", Text = "The thing you know in the abstract, but which you have to see, is the vastness of the place and how little relationship one side of it has to another. Mostly, the landscape is just unbelievably beautiful. You do a lot of looking and not that much thinking.", Author = "Kamila Shamsie" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pierre_Nguy%E1%BB%85n_V%C4%83n_Vi%C3%AAn", Text = "We live in an era in which information spreads quickly, most Vietnamese Catholics cannot benefit from it.", Author = "Pierre Nguyễn Văn Viên" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rosabeth_Moss_Kanter", Text = "Everything looks like a failure in the middle.", Author = "Rosabeth Moss Kanter" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Daniel_Cohn-Bendit", Text = "A spectre is haunting Europe - the spectre of student revolt. All the powers of old Europe have entered into a holy alliance to exorcize this spectre : Pope and Central Committee, Kissinger and de Gaulle, French Communists and German police-spies.", Author = "Daniel Cohn-Bendit" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ammon_Hennacy", Text = "Oh judge! Your damn laws! The good people don't need them, and the bad people don't obey them.", Author = "Ammon Hennacy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_O%27Hara", Text = "I have work to do, and I am afraid not to do it.", Author = "John O'Hara" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Keiko_Bonk", Text = "I come back. The same things are happening.", Author = "Keiko Bonk" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Michael_Harris_%28mathematician%29", Text = "Langlands and Grothendieck are both (at least) Giants by any measure, and both were consciously successors of Galois.", Author = "Michael Harris (mathematician)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gabrielle_Roy", Text = "Could we ever know each other in the slightest without the arts?", Author = "Gabrielle Roy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Viliame_Rovabokola", Text = "I know it's difficult to forget the past but I urge everyone here today to try and move the country forward.", Author = "Viliame Rovabokola" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_X-Files%3A_Fight_The_Future", Text = "Scully, you know that face I just showed you? I'm making it again.", Author = "The X-Files: Fight The Future" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Claire_Palley", Text = "The objection that one cannot legislate to change the hearts and minds of men is a red herring, when the law seeks to hit at actions not at attitudes.", Author = "Claire Palley" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Larry_Sanger", Text = "Suppose that, as is perfectly possible, Wikipedia continues producing articles at a rate of 1,000 per month. In seven years, it would have 84,000 articles.", Author = "Larry Sanger" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fyodor_Tyutchev", Text = "How can a heart expression find? How should another know your mind? Will he discern what quickens you? A thought once uttered is untrue.", Author = "Fyodor Tyutchev" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eduardo_Mart%C3%ADnez_Somalo", Text = "We cannot call up an army of peace but we can call up a spiritual army to implore peace, so that the fact that one day of peace is better than years of war will penetrate peoples’ consciences.", Author = "Eduardo Martínez Somalo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Susannah_Constantine", Text = "What it is, is that you're (Trinny) the accelerator and I'm (Susannah) the break. And that's why it works.", Author = "Susannah Constantine" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Vitaliy_Skomarovskyi", Text = "All that we are experiencing now, the horror of war, is actually so terrible because it touches, above all, ordinary people, poor people who lived normally in families and led normal lives, and now our boys die at the front, women become widows, children become orphans.", Author = "Vitaliy Skomarovskyi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tan_Kheng_Hua", Text = "I’ve gone through so many dark periods of my life, but my art has always been there. I firmly believe in this way of living, and I hope to die like this.", Author = "Tan Kheng Hua" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Gilmore", Text = "The Net interprets censorship as damage and routes around it.", Author = "John Gilmore" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Asif_Ali_Zardari", Text = "Journalists are bigger terrorists than terrorists themselves.", Author = "Asif Ali Zardari" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tommy_Farr", Text = "Every time I hear the name Joe Louis, my nose starts to bleed.", Author = "Tommy Farr" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Sacred_Exchange_between_Saint_Francis_and_Lady_Poverty", Text = "Holy poverty … is the foundation and guardian of all virtues.", Author = "The Sacred Exchange between Saint Francis and Lady Poverty" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Harsanyi", Text = "If somebody prefers an income distribution more favorable to the poor for the sole reason that he is poor himself, this can hardly be considered as a genuine value judgment on social welfare.", Author = "John Harsanyi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anwar_Shaikh", Text = "I was not only born and bred as a Muslim but also fought grimly for the glory of Islam. Even today, my loved ones are Muslim. There is no way I can be anti-Muslim.", Author = "Anwar Shaikh" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Phenomenon", Text = "This kid may be the key not just to all human potential, but to all spiritual unexplained paranormal phenomena. The key to everything in The X-Files.", Author = "Phenomenon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Margaret_Busby", Text = "It's really just showing that there is more that you could be enjoying, that you could be learning from, that you could be reading.", Author = "Margaret Busby" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Richard_Johnson_%2816th-century_writer%29", Text = "Deaths pale flags advanced in his Cheeks.", Author = "Richard Johnson (16th-century writer)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Scott_Lynch", Text = "Better to say nothing and be thought a fool, said Amarelle, than to interfere in the business of wizards and remove all doubt.", Author = "Scott Lynch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christian_Drosten", Text = "We don't really know enough about this (COVID-19) disease to be sure what it means when the viral load decreases in the throat, for instance.", Author = "Christian Drosten" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tracy_Drain", Text = "We're going to a place that's super cool and is a juicy, juicy science target", Author = "Tracy Drain" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Lone_Ranger_Rides_Again", Text = "YOUR PHANTOM HERO OF THE AIR WAVES RETURNS TO FLESH-AND-BLOOD REEL LIFE With Tonto and Silver in an ALL-NEW series of fifteen whirlwind adventures!", Author = "The Lone Ranger Rides Again" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bert_Leston_Taylor", Text = "A bore is a man who, when you ask how he is, tells you.", Author = "Bert Leston Taylor" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Samuel_Butler_%28poet%29", Text = "There are more fools than knaves in the world, else the knaves would not have enough to live upon.", Author = "Samuel Butler (poet)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Maria_Troncatti", Text = "Detachment was something that cost me a lot: detachment from my parents, Superiors, town, language, everything; when I boarded the steamer I said goodbye forever. We will see each other again in heaven.", Author = "Maria Troncatti" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eug%C3%A8ne_Burnouf", Text = "We will study India with its philosophy and its myths, its literature, its laws and its language. Nay It is more than India it IS a page of the origin of the world that we will attempt to decipher.", Author = "Eugène Burnouf" },
        new Quote { Id = "https://en.wikiquote.org/wiki/McQ", Text = "Rosey, if this is a shine, I'm coming back and iron your face.", Author = "McQ" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Amess", Text = "Raped the town of Basildon .. I thought the whole world knew there was a place called Basildon, but apparently the Boundary Commission have never heard of it.", Author = "David Amess" },
        new Quote { Id = "https://en.wikiquote.org/wiki/D.E.B.S.", Text = "I guess I'll see you around...same 'bat time' or whatever.", Author = "D.E.B.S." },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Wilson_Lynd", Text = "The art of writing history is the art of emphasizing the significant facts at the expense of the insignificant. And it is the same in every field of knowledge. Knowledge is power only if a man knows what facts not to bother about.", Author = "Robert Wilson Lynd" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kafayat_Oyetola", Text = "Governance exposes you. I am a shy person but despite that, I have to be seeing people, whether I like them or not. I must speak with them. Even your enemies you have to make friends with them. This has been one of the greatest lessons I have learnt.", Author = "Kafayat Oyetola" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Vilayanur_S._Ramachandran", Text = "Here is this mass of jelly - three pound mass of jelly - that you can hold in the palm of your hand, and it can contemplate the vastness of interstellar space, it can contemplate the meaning of infinity, and it can contemplate itself contemplating the meaning of infinity.", Author = "Vilayanur S. Ramachandran" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Yang_Yongqiang", Text = "I feel that God has always been by my side, leaning down to help me build cornerstones and solve difficulties one by one.", Author = "Joseph Yang Yongqiang" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Music", Text = "To me, the wonderful thing about music is a love affair between the performer and the composer, and between the composer and his audience. This love affair is a tripartite thing.", Author = "Music" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Daniel_Ellsberg", Text = "That was a documentary!", Author = "Daniel Ellsberg" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Al_B._Sure%21", Text = "I can tell you how I feel about you night and day.", Author = "Al B. Sure!" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Weird_Woman", Text = "Black magic, island witchcraft, voodoo rituals and nonsense. Proven nonsense.", Author = "Weird Woman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Achy_Obejas", Text = "Memory, about the futile struggle to remember. It’s a eulogy to all the people who flee the terrible conditions in their home countries, desperately hoping for a better life here, and never make it.", Author = "Achy Obejas" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Steven_Boyett", Text = "You had to be a virgin to touch a unicorn...A flush crept up my neck. Okay, so I’d touched her. Being a virgin had some advantages after all. Hooray.", Author = "Steven Boyett" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Virgil_Miller_Newton", Text = "It was evident that the treatment program’s building was a place where miracles happen.", Author = "Virgil Miller Newton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tayeb_Salih", Text = "It was a steamingly hot July night, the Nile that year having experienced one of those floodings that occur once every twenty or thirty years and become legendary - something for fathers to talk to their sons about.", Author = "Tayeb Salih" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Captain_Beefheart", Text = "A squid eating dough in a polyethylene bag is fast and bulbous. Got me?", Author = "Captain Beefheart" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sally_Falk_Moore", Text = "Sally was an elegant woman: a classical beauty and with exquisite manners. Given the challenges of being a woman of her generation in the legal world and in academia — someone hard-nosed, strong-willed, and determined — it would be unfortunate if she went down into history as delicate.", Author = "Sally Falk Moore" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gustave_Courbet", Text = "We finally saw the sea, the horizonless sea – how odd for a mountaindweller. We saw the beautiful boats that sail on it. It is too inviting, one feels carried away, one would leave to see the whole world.", Author = "Gustave Courbet" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Scorpion_King%3A_Rise_of_the_Akkadian", Text = "My name is Magus. I have been searching for a man of your talent to assist me. I am conducting an experiment, and need a man of strength such as yours if my work is to be successful.", Author = "The Scorpion King: Rise of the Akkadian" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jimmy_Kimmel", Text = "We're going to give men what they really want to see on TV. Monkeys, midgets, beer drinking and women jumping on trampolines.", Author = "Jimmy Kimmel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Yoshihide_Suga", Text = "We cannot realize financial reconstruction and enhance social security without a strong economy. It’s impossible to pursue foreign and security policy based on our stance without a strong economy.", Author = "Yoshihide Suga" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Arifur_Rahman", Text = "Freedom of speech is very important because it is a fundamental part of our rights. Everyone must be allowed to say what they mean.", Author = "Arifur Rahman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/A_History_of_Violence_%28film%29", Text = "You should ask Tom... how come he's so good at killing people?", Author = "A History of Violence (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Amos_Luzzatto", Text = "In order to uproot all spirit of opposition I believe it is fundamental to implement a broad educational endeavor, because certain prejudices of the Western world cannot be addressed in a few hours.", Author = "Amos Luzzatto" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Final_Fantasy_XI", Text = "Everyone: I hate Tarutaru and so should you.", Author = "Final Fantasy XI" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Shneur_Zalman_of_Liadi", Text = "Tachlis Brias Olam Hazeh, Hu she'nisaivah Hakadosh Ba-ruch Hu Le'hios Lo Dirah B'tachtonim.-'The ultimate purpose of the creation of this physical world, is that G-d Desired to have a dwelling-place in the lower world.'", Author = "Shneur Zalman of Liadi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Conor_Oberst", Text = "I never fuck with Facebook. I absolutely despise social networking. I think it's truly going to result in the destruction of mankind. Sometimes I just wish I didn't live in this time. Before, there was so much more freedom and privacy, and you could truly escape places.", Author = "Conor Oberst" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nicola_Barker", Text = "There are writers who exist to confirm people's feelings about themselves and to make them feel comforted or not alone. That's the opposite to what I do. I'm presenting people with unacceptable or hostile characters, and my desire is to make them understood.", Author = "Nicola Barker" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Wolcot", Text = "What rage for fame attends both great and small!Better be damned than mentioned not at all.", Author = "John Wolcot" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Douglas_John_Hall", Text = "Princeton Lectures on Youth, Church, and Culture", Author = "Douglas John Hall" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Glover_%28businesswoman%29", Text = "The first and most important point is to stay calm. The world is obviously changing around us all the time, but we need to keep a clear head in order to react and communicate effectively.", Author = "Anne Glover (businesswoman)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Paul_Nitze", Text = "Some people say there are two policies in the executive branch … one is mine and the other is the president's, which is marginally so. Some of the things I've said are different from what the president has said, but all the things I have said have been approved by the president.", Author = "Paul Nitze" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rush_Limbaugh", Text = "Take that bone out of your nose and call me back.", Author = "Rush Limbaugh" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alison_Loehnis", Text = "I got totally made fun of for my tiny skirts.", Author = "Alison Loehnis" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kelvin_Kiptum", Text = "My secret is training. Not any other thing.", Author = "Kelvin Kiptum" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Huangbo_Xiyun", Text = "A perception, sudden as blinking, that subject and object are one, will lead to a deeply mysterious understanding; and by this understanding you will awaken to the truth.", Author = "Huangbo Xiyun" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Brandon_Sanderson", Text = "Hrathen turned to Dial. The first step in taking control of a nation, Arteth, is the simplest. You find someone to hate.", Author = "Brandon Sanderson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Patrice_de_MacMahon", Text = "C'est vous le negre? Très bien. Continuez, mon ami, continuez!", Author = "Patrice de MacMahon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Israel_Matseke_Zulu", Text = "I grew up in court. I knew the justice system. Boys will be boys was the judgement and I knew the judgement before it was even given.", Author = "Israel Matseke Zulu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Aqua_Teen_Hunger_Force_%28Season_5%29", Text = "Meatwad: Yippie-ka yay, motherfucker!", Author = "Aqua Teen Hunger Force (Season 5)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Agnes_Asangalisa_Chigabatia", Text = "When the people understand that it is pure love you have for them, then we can come back to the drawing table and talk politics.", Author = "Agnes Asangalisa Chigabatia" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Luke_Wadding", Text = "He was a man of the most thorough loyalty to his country and to his order, of extensive learning, free from all desire for personal aggrandisement, and of an unlimited benevolence.", Author = "Luke Wadding" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Happy_Feet", Text = "Guys, we have a mystery here. A mind-boggling mystery.", Author = "Happy Feet" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jane_Baker_%28mayor%29", Text = "Jane was the leader, and she fit the role perfectly.", Author = "Jane Baker (mayor)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jacques_Maritain", Text = "Whereas the intelligence of God is both the cause and the measure of the truth of things, things are both the cause and the measure of the truth of our intelligence.", Author = "Jacques Maritain" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Edwin_Boring", Text = "Sometimes I fear that, if Harvard does not give up trying to turn itself from an Institution of Learning into an Educational Institution, we may have a generation of professors whose duty it will be to disseminate information which they have not the time to acquire.", Author = "Edwin Boring" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Samrawit_Fikru", Text = "Thank you Dr. Artist Tewodros Kassahun for supporting our effort to build the creative economy for the generation to come.", Author = "Samrawit Fikru" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Michelle_Abueng", Text = "I like dreaming because it is only then that they can turn into reality.", Author = "Michelle Abueng" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rachel_Baard", Text = "We live in a different time than we lived in a year ago. And I wish we were sitting here talking about this dystopian fictional world, and how glad we are that we’re not intent.", Author = "Rachel Baard" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Titilope_Sonuga", Text = "Do not romanticize suffering. There is nothing poetic about a love that breaks your spirit.", Author = "Titilope Sonuga" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ruby_Bridges", Text = "You cannot look at a person and tell whether they're good or bad.", Author = "Ruby Bridges" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Oral_tradition", Text = "The oral tradition is vital; it heals itself and the tribal web by adapting to the flow of the present while never relinquishing its connection to the past. Its adaptability has always been required, as many generations have experienced.", Author = "Oral tradition" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kenny_vs._Spenny", Text = "Kenny: The only reason I'm kinda looking forward to it is I hear you actually can go crazy and hallucinate.", Author = "Kenny vs. Spenny" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jibanananda_Das", Text = "Into the half light and shadow go I. Within my head", Author = "Jibanananda Das" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Annettee_Nakimuli", Text = "I felt like we were accomplices in this war of sorts. People say we do not remember the words of our enemies but the silence of our friends. I did not want to accept that it was beyond hope.’", Author = "Annettee Nakimuli" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Arthur_Joseph_Colgan", Text = "As a priest I have tried to contribute to the formation of lay men and women and to animating their active role in the Church's mission of Evangelization. As a Bishop, I hope to continue doing so. In my ministry I hope to make visible and real the Church's preferential option for the poor.", Author = "Arthur Joseph Colgan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/3D_Monster_Maze", Text = "ROLL UP, ROLL UP, SEE THE AMAZING TYRANNOSAURUS REX KING OF THE DINOSAURS IN HIS LAIR. PERFECTLY PRESERVED IN SILICON SINCE PREHISTORIC TIMES, HE IS BROUGHT TO YOU FOR YOUR ENTERTAINMENT AND EXHILARATION.", Author = "3D Monster Maze" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Denison", Text = "A serjeant is a soldier with a halbert, and a drummer is a soldier with a drum.", Author = "Thomas Denison" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Echo", Text = "Let echo, too, perform her part,Prolonging every note with art;And in a low expiring strain,Play all the comfort o'er again.", Author = "Echo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Motiuk", Text = "We like to do all the talking, but it's so important to listen.", Author = "David Motiuk" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Lacaton", Text = "Living well in the city is the most important challenge of our time and our generation.", Author = "Anne Lacaton" },
